const Rank=require("../models/rankModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_rank=(n,a,e)=>{Rank.create(n.body).then(e=>{a.status(200).send(e)}).catch(e=>{a.status(422).send(handleErrors(e,n,"rank"))})},get_ranks=(e,n,a)=>{Rank.find({}).sort({rank_number:-1}).lean().then(e=>n.status(200).send({ranks:e})).catch(a)},get_admin_ranks=(e,a,t)=>{const r=e.query.page-1||0;Rank.find({}).count().then(n=>{Rank.find({}).sort({rank_number:-1}).skip(30*r).limit(30).then(e=>a.status(200).send({ranks:e,total_ranks:n,per_page:30})).catch(t)})},get_single_rank=(e,n,a)=>{Rank.findById({_id:e.params.id}).then(e=>n.status(200).send(e)).catch(a)},update_rank=(e,n,a)=>{Rank.findByIdAndUpdate({_id:e.params.id},e.body,{new:!0}).then(e=>n.status(200).send(e)).catch(a)},delete_rank=(e,n,a)=>{Rank.findByIdAndDelete({_id:e.params.id},{new:!0}).then(e=>n.status(200).send(e)).catch(a)};module.exports={create_rank:create_rank,update_rank:update_rank,get_single_rank:get_single_rank,get_admin_ranks:get_admin_ranks,get_ranks:get_ranks,delete_rank:delete_rank};